## Caller usage

```ts
// src/worker.ts. The browser never supplies a tenant identifier.
const identity = await verifyAccess(request, env.ACCESS);
const tenant = await deriveTenantKey(identity);

const supervisor = env.SUPERVISOR.getByName(supervisorObjectName(tenant));
return supervisor.fetch(request);
```

```ts
// Owner-only generation endpoint. The mutable facet has no equivalent binding.
const identity = await verifyAccess(request, env.ACCESS);
const tenant = await deriveTenantKey(identity);

return env.SUPERVISOR.getByName(supervisorObjectName(tenant)).controlGeneration(
  parseOwnerGenerationRequest(request),
);
```

```ts
// Trusted P0 controller. Both names derive from the same verified identity.
const tenant = await deriveTenantKey(await verifyAccess(request, env.ACCESS));
const host = env.WORKSPACE_HOST.getByName(workspaceHostObjectName(tenant));
const artifact = await host.buildP0ProbeModuleMap(P0_PROBE_HARNESS_COMMIT);

return env.SUPERVISOR.getByName(supervisorObjectName(tenant)).runP0Probe({
  workspaceHostId: env.WORKSPACE_HOST.idFromName(workspaceHostObjectName(tenant)).toString(),
  artifact,
});
```

```ts
// Mutable probe facet. HOST is a loopback WorkerEntrypoint binding, not a namespace.
const document = await env.HOST.compareAndSwapDocument({
  key: "p0/probe-result",
  expectedRevision: null,
  bytes: new TextEncoder().encode("started").buffer,
});

const workspace = await env.HOST.runP0WorkspaceProbe();
const model = await fetch(MODEL_PROBE_URL, fixedModelProbeRequest());

return Response.json(toProbeResult(document, workspace, model));
```

`POST /__p0/probe` returns one complete JSON `ProbeResult` after every operation settles. It does not stream, create relay credit, or expose generation controls.

## Branded types

```ts
declare const accessSubjectBrand: unique symbol;
declare const accessApplicationBrand: unique symbol;
declare const tenantKeyBrand: unique symbol;
declare const documentKeyBrand: unique symbol;
declare const harnessCommitBrand: unique symbol;

type AccessSubject = string & {
  readonly [accessSubjectBrand]: "AccessSubject";
};

type AccessApplicationId = string & {
  readonly [accessApplicationBrand]: "AccessApplicationId";
};

type TenantKey = string & {
  readonly [tenantKeyBrand]: "TenantKey";
};

type DocumentKey = string & {
  readonly [documentKeyBrand]: "DocumentKey";
};

type HarnessCommit = string & {
  readonly [harnessCommitBrand]: "HarnessCommit";
};

type VerifiedAccessIdentity = Readonly<{
  subject: AccessSubject;
  applicationId: AccessApplicationId;
}>;

type DocumentRead =
  | Readonly<{ kind: "missing" }>
  | Readonly<{ kind: "found"; revision: number; bytes: ArrayBuffer }>;

type DocumentWrite =
  | Readonly<{ kind: "written"; revision: number }>
  | Readonly<{ kind: "conflict"; actualRevision: number | null }>;

type P0WorkspaceObservation = Readonly<{
  filePersisted: boolean;
  commandExitCode: number;
  commandOutput: string;
}>;

type ProbeOperation =
  | "document-write"
  | "document-read"
  | "workspace-file"
  | "workspace-command"
  | "model"
  | "unapproved-egress";

type ProbeResult = Readonly<{
  operations: readonly Readonly<{
    operation: ProbeOperation;
    durationMs: number;
    outcome: "succeeded" | "rejected-as-expected" | "failed";
    error: string | null;
  }>[];
}>;
```

`TenantKey` is `tenant-v1:` plus SHA-256 over an unambiguous encoding of the Access application ID and stable subject. The key is the only identity value used in Durable Object names. Raw claims never enter Durable Object storage, facet props, or the dynamic module map.

## Function signatures

```ts
async function verifyAccess(
  request: Request,
  verifier: AccessVerifier,
