}

function parseDocumentKey(value: string): DocumentKey | undefined {
  throw new Error("not implemented");
}

interface MainHarnessHostBinding {
  readDocument(input: Readonly<{ key: string }>): Promise<DocumentRead>;

  compareAndSwapDocument(
    input: Readonly<{
      key: string;
      expectedRevision: number | null;
      bytes: ArrayBuffer;
    }>,
