  }

  buildP0ProbeModuleMap(commit: HarnessCommit): Promise<MainHarnessArtifactInput> {
    throw new Error("not implemented");
  }
}

class MainHarnessHostProxy
  extends WorkerEntrypoint<StaticEnv, Readonly<{ binding: "WORKSPACE_HOST"; id: string }>>
  implements MainHarnessHostBinding
{
  readDocument(input: Readonly<{ key: string }>): Promise<DocumentRead> {
    throw new Error("not implemented");
  }

  compareAndSwapDocument(
    input: Readonly<{
      key: string;
      expectedRevision: number | null;
      bytes: ArrayBuffer;
    }>,
  ): Promise<DocumentWrite> {
    throw new Error("not implemented");
  }

  runP0WorkspaceProbe(): Promise<P0WorkspaceObservation> {
    throw new Error("not implemented");
  }
}

class RestrictedModelEgress extends WorkerEntrypoint<StaticEnv> {
  override fetch(request: Request): Promise<Response> {
    throw new Error("not implemented");
  }
}

class ProbeMainFacet extends DurableObject<Readonly<{ HOST: MainHarnessHostBinding }>> {
  override fetch(request: Request): Promise<Response> {
    throw new Error("not implemented");
  }
}
```

`WorkspaceHost` validates document key size, document byte size, and revision shape at its RPC boundary. It stores bytes and revisions without parsing their schema. `buildP0ProbeModuleMap` is deliberately absent from `MainHarnessHostBinding`, so only static trusted code can ask Computer to build executable code.

## Module map

```text
src/worker.ts
  verifies Access
  derives TenantKey
  selects Supervisor and WorkspaceHost names
  owns owner-only generation routes and the P0 controller route
  top-level exports WorkspaceHost, MainHarnessHostProxy,
  RestrictedModelEgress, and Computer's WorkspaceProxy

src/workspace-host/
  static container-enabled Durable Object
  owns Computer, durable opaque documents, and P0 module-map build work
  uses ctx.exports.WorkspaceProxy internally for Computer's container callback

src/p0/
  probe-main-facet.ts
  probe-loader.ts
  probe-controller.ts
  restricted-model-egress.ts

src/supervisor/
  adds runP0Probe only
  creates ctx.exports.MainHarnessHostProxy with plain { binding, id } props
  creates ctx.exports.RestrictedModelEgress
  mounts the probe through the existing ordinary fetch boundary

src/facet/
  remains unchanged for Night 2
```

The P0 Dynamic Worker receives exactly this loader configuration:

```ts
{
  compatibilityDate: "2025-01-01",
  mainModule: "p0-probe-main.js",
  modules: { "p0-probe-main.js": { js: probeSource } },
  env: {
    HOST: ctx.exports.MainHarnessHostProxy({
      props: { binding: "WORKSPACE_HOST", id: workspaceHostId },
    }),
  },
  globalOutbound: ctx.exports.RestrictedModelEgress(),
}
```

It receives no `SUPERVISOR`, `WORKSPACE_HOST`, `LOADER`, `AI`, R2 binding, credential, `WorkerLoader`, `RpcTarget`, or general `fetch` capability. `WorkspaceProxy`, `MainHarnessHostProxy`, and `RestrictedModelEgress` must be top-level exports because Computer's pinned `proxy.ts` establishes `ctx.exports.<Entrypoint>` loopback bindings as the supported values that survive the loader path.

## Flow

1. The static Worker validates the Access token and constructs `VerifiedAccessIdentity`. It hashes the stable subject and application ID into one `TenantKey`.

2. The Worker derives both names from that key. The Supervisor and WorkspaceHost each receive their own namespace-local object with the same tenant identity.

3. A trusted P0 controller asks WorkspaceHost to build the probe module map through Computer. Mutable code never supplies module bytes or a claimed commit.

4. The Supervisor creates a `MainHarnessHostProxy` through `ctx.exports` using only the WorkspaceHost binding name and object ID. It passes that loopback binding to the Worker Loader.

5. The Supervisor passes a second `ctx.exports` binding as `globalOutbound`. `RestrictedModelEgress` accepts only the synthetic fixed model URL, exact POST shape, and configured model. It rebuilds the request using its static gateway configuration and `AI` binding, then calls `createGatewayBindingFetch`.

6. The facet performs its fixed probe, saves opaque probe bytes through CAS, invokes the one workspace operation, makes one model request, and verifies that an unrelated URL is rejected. It returns a buffered `ProbeResult`.

7. Owner generation actions remain static Worker routes protected by Access. They call Supervisor control APIs directly. The facet has no control binding and cannot write generation or recovery state.

## Invariants

- One verified `(applicationId, subject)` pair maps deterministically to one `TenantKey`. Different applications or subjects map to different keys.
- The request never chooses a tenant key, Supervisor name, or WorkspaceHost name.
- WorkspaceHost is static and tenant-keyed. Facet replacement and eviction cannot discard its Computer workspace or opaque documents.
- Documents use revision CAS. A stale writer receives `conflict` and is never retried implicitly.
- WorkspaceHost does not parse, migrate, list, or interpret document payloads.
- The dynamic facet gets one host capability with three operations. It never receives Computer itself or a raw `WorkspaceStub`.
- The dynamic facet has no Durable Object namespace, account credential, loader, general outbound fetch, or generation-state write path.
- Model egress rejects every URL except the fixed synthetic route, rejects non-POST or malformed bodies, strips caller-provided auth headers, and uses the static binding route only.
- The P0 probe is buffered and ordinary. It does not alter the current incomplete relay-completion policy or gain known-good credit.
- `GET /` remains a cheap ordinary startup request under ADR-0029.

## Tests

- Access parsing rejects missing, invalid, or mismatched claims. Equal verified identities derive equal keys. Changing either application ID or subject changes the key.
- Worker routing proves a caller-controlled header, path segment, or body cannot choose another tenant's Supervisor or WorkspaceHost.
- Document tests cover initial write, matching revision, stale conflict, byte-for-byte opacity, and persistence after a fresh WorkspaceHost incarnation.
- Proxy tests capture loader configuration and prove that its only dynamic `env` key is `HOST`, whose value comes from `ctx.exports.MainHarnessHostProxy`.
- A negative loader test attempts to pass a namespace, function, `RpcTarget`, and `WorkerLoader`. Each is rejected before the design can depend on it.
- Restricted-egress tests prove the one accepted request reaches a fake `AI.gateway().run`, while another origin, method, provider path, model, auth header, or malformed JSON cannot.
- Probe-facet tests use a fake host port. They verify document CAS, file work, command observation, expected egress rejection, complete JSON serialization, and no response until all operations settle.
- Supervisor tests prove `runP0Probe` mounts a cold facet through ordinary `fetch`, while owner generation APIs remain unreachable from the probe facet.
- `pnpm verify` is the local gate. It cannot prove that a loopback WorkerEntrypoint survives deployed loader cloning.

## Paid probe shape

Deploy a dedicated P0 Worker with an isolated Worker Loader, Supervisor namespace, WorkspaceHost namespace, container class, R2 bucket, Access test application, route, and tenant subject. Do not import production bindings.

The controller records a raw JSON artifact containing the deployed SHA, derived object names, module-map byte count, operation outputs, cold and warm durations, and unredacted platform errors. It runs this sequence:

1. Resolve both object names from the Access test identity.
2. Use Computer to write a file, restart or evict the host and facet, then read that file.
3. Run one container command and retain stdout, stderr, exit code, and timing.
4. Build the fixed probe harness commit through Computer, load its module map under that exact commit, cold-mount the facet, and perform `GET /`.
5. Run `POST /__p0/probe` through Supervisor. Confirm the model response uses the fixed route.
6. Attempt `fetch("https://example.com")` inside the facet. Confirm the restricted egress rejects it and no request reaches the destination.
7. Preserve the raw evidence. Stop immediately on `DataCloneError`, loader rejection, an unbounded outbound path, failed persistence, or a capability that requires a namespace or credential in mutable code.

## Tradeoffs and synthesis decision

The chosen shape uses a custom loopback host proxy rather than Computer's exported `WorkspaceServiceProxy`. It exposes a smaller interface, so the facet cannot acquire Computer's full workspace surface or future administrative methods. The proxy still follows the same pinned Computer rule by resolving the namespace only inside a top-level `WorkerEntrypoint`.

We accept a temporary P0-specific loader beside `src/facet/index.ts` in exchange for leaving the current fixture and SQLite artifact path untouched. Night 2 proves the platform boundary. P1 can replace that probe loader once the paid evidence is real.

We accept an opaque document store without document enumeration or schema checks in exchange for keeping session ownership with the mutable generation. Revision CAS is the one host-level concurrency rule because it prevents silent transcript overwrite without teaching the host Pi's schema.

We accept the synthetic model URL and a strict request adapter in exchange for keeping account routing, gateway configuration, and provider credentials outside the dynamic module map. The facet can still consume model output, but it cannot select a provider or turn `fetch` into an egress tunnel.

Passing `DurableObjectNamespace` values through loader `env` lost because workerd cannot clone them. Passing a raw `WorkspaceStub` lost because it exposes Computer rather than the P0 operations the facet needs. Giving the facet an AI binding lost because it moves account capability into mutable code.

Foundational Thinking selected the tenant-keyed host and opaque CAS record before the probe behavior. Model the Domain selected the explicit document-result union instead of optional revision fields. Boundary Discipline puts Access parsing, document validation, and egress validation at their respective edges. Type System Discipline brands identity and commit values while keeping RPC and durable values plain. Minimize Reader Load keeps the mutable facet’s authority visible in one `HOST` binding and one outbound route.

# Night 2 design package

## Problem

Night 2 has to prove that a Cloudflare Access identity can reach a durable Computer workspace and one model route through a Dynamic Worker facet, without any of the four forbidden things crossing into mutable code. The shape is non-obvious because the loader boundary destroys most of what you would normally pass. Prior workerd evidence says loader `env` values go through structured clone, so a `DurableObjectNamespace`, a function, an `RpcTarget`, or a `WorkerLoader` cannot be handed to a generation. Computer's `proxy.ts` says the one thing that does survive is a loopback binding produced by `ctx.exports.<ClassName>(...)` for a top-level exported `WorkerEntrypoint`. `container-host.ts:133` says the container backend needs `ctx.container`, which a facet does not have, so the workspace must live in a statically deployed Durable Object. ADR-0024 says the generation owns the model loop, so the loop cannot move into the container. ADR-0003 says only the Supervisor writes generation state. The feature map says the model gets no generation-control tool at all.

Those constraints leave one viable skeleton. The design work is in what the capability surface looks like, not in where the pieces live.

## Usage (caller's view)

**1. The Worker route. This is the whole tenant derivation.**

```ts
// src/worker.ts
import { verifyAccessIdentity, deriveTenantKey, tenantRoutes } from "./tenant/index.js";

export default {
  async fetch(request: Request, env: WorkerEnv): Promise<Response> {
    const identity = await verifyAccessIdentity(request, env.ACCESS_POLICY, accessKeys, Date.now());
    if (identity.isErr()) {
      return new Response(identity.error.code, { status: 403 });
    }

    const key = await deriveTenantKey(identity.value);
    const routes = tenantRoutes(env, key);
    return routes.supervisor.fetch(request);
  },
};

export { Supervisor } from "./supervisor/index.js";
export { WorkspaceHost } from "./workspace-host/index.js";
export { MainHarnessHostProxy } from "./host-capability/index.js";
export { ModelGatewayOutbound } from "./model-route/index.js";
export { WorkspaceProxy } from "@cf-stumble/computer";
```

There is no `parseTenantKey`. A `TenantKey` cannot be built from a request field, because the only function that returns one takes an `AccessIdentity`, and the only function that returns an `AccessIdentity` verifies a signature.

**2. The Supervisor mounting the active generation.** This is where attenuation happens, in immutable code.

```ts
// inside Supervisor.fetch
const host = this.ctx.exports.MainHarnessHostProxy({
  props: {
    workspaceBinding: "WORKSPACE_HOST",
    workspaceHostId: this.env.WORKSPACE_HOST.idFromName(this.ctx.id.name ?? "").toString(),
    workspaceRoot: "/workspace/repo",
    generationLabel: active.generation.label,
  },
});

const mounted = loadMainFacet({
  loader: this.env.LOADER,
  artifact,
  host,
  outbound: this.ctx.exports.ModelGatewayOutbound(),
  model: { baseUrl: MODEL_BASE_URL, id: MODEL_ID },
});
```

Everything in `props` is a string or a number. The root and the generation label come from the Supervisor, so mutable code cannot widen its own scope or claim another generation.

**3. Mutable code inside the generation, running one buffered turn.**

```ts
// generation source, src/main-facet.ts
export class MainFacet extends DurableObject<MainFacetEnv> {
  override async fetch(request: Request): Promise<Response> {
    if (new URL(request.url).pathname === "/") {
      return new Response("ready");
    }

    const turn = parseTurnRequest(await request.text());
    const saved = await this.env.HOST.readDocument(`sessions/${turn.sessionId}`);
    const session = saved.found ? restoreSession(saved.value) : emptySession(turn.sessionId);

    const before = await this.env.HOST.readFile("src/index.ts");
    await this.env.HOST.writeFile("src/index.ts", patched(before));
    const check = await this.env.HOST.exec({
      argv: ["pnpm", "test"],
      cwd: ".",
      timeoutMs: 120_000,
    });

    const written = await this.env.HOST.writeDocument({
      key: `sessions/${turn.sessionId}`,
      expectedRevision: saved.found ? saved.revision : null,
      value: JSON.stringify(appendTurn(session, check)),
    });
    if (!written.ok) {
      return new Response(written.code, { status: 409 });
    }

    return Response.json(turnResponse(check, written.revision), {
      headers: { "x-cf-stumble-completion": "turn-v1" },
    });
  }
}
```

The facet holds one binding. It never sees Computer, a namespace, a stub it must keep alive, an account id, or a credential. Its `fetch` to the model provider goes to `env.MODEL_BASE_URL`, and the runtime routes that subrequest through `globalOutbound`, so the restriction is structural rather than a rule the harness is asked to follow.

**4. The Night 2 probe facet.** Throwaway source, not product code.

```ts
// src/probe/facet-source.ts, loaded through the same loadMainFacet path
export class MainFacet extends DurableObject<MainFacetEnv> {
  override async fetch(): Promise<Response> {
    const steps: ProbeStep[] = [];
    steps.push(await step("document-write-read-roundtrip", () => roundTripDocument(this.env.HOST)));
    steps.push(await step("container-command", () => this.env.HOST.exec({ argv: ["node", "-v"], cwd: ".", timeoutMs: 30_000 })));
    steps.push(await step("model-route-allowed", () => fetch(`${this.env.MODEL_BASE_URL}/chat/completions`, probeBody)));
    steps.push(await step("model-route-denied", () => fetch("https://example.com/")));
    return Response.json({ version: 1, steps } satisfies ProbeReportBody);
  }
}
```

## Branded types

```ts
// src/tenant/index.ts
declare const accessSubjectBrand: unique symbol;
declare const accessAudienceBrand: unique symbol;
declare const tenantKeyBrand: unique symbol;

/** The Access `sub` claim. Stable across an email change at the IdP. */
export type AccessSubject = string & { readonly [accessSubjectBrand]: "AccessSubject" };

/** The configured Access application AUD tag. Never read from a request. */
export type AccessAudience = string & { readonly [accessAudienceBrand]: "AccessAudience" };

/**
 * The Durable Object name for one tenant.
 * Only `deriveTenantKey` produces one, and it takes a verified identity,
 * so no request field can select a tenant.
 */
export type TenantKey = string & { readonly [tenantKeyBrand]: "TenantKey" };

/** Produced only by `verifyAccessIdentity`. Unforgeable because its fields are branded. */
export type AccessIdentity = {
  readonly subject: AccessSubject;
  readonly audience: AccessAudience;
};
```

```ts
// src/workspace-host/documents/index.ts
declare const documentKeyBrand: unique symbol;
declare const documentRevisionBrand: unique symbol;

/**
 * Slash-separated lowercase segments, at most 8 deep and 256 characters total.
 * The grammar exists so the host can scope by prefix and bound a row
 * without ever looking inside a value.
 */
export type DocumentKey = string & { readonly [documentKeyBrand]: "DocumentKey" };

/** Strictly increasing per key. Revision 1 is the first write. */
export type DocumentRevision = number & { readonly [documentRevisionBrand]: "DocumentRevision" };
```

```ts
// src/workspace-host/computer/index.ts
declare const workspacePathBrand: unique symbol;
declare const workspaceRootBrand: unique symbol;
declare const execArgvBrand: unique symbol;

/**
 * A relative POSIX path with no `..` segment, no leading slash, no backslash,
 * and no NUL. Escaping the root is unrepresentable rather than checked later.
 */
export type WorkspacePath = string & { readonly [workspacePathBrand]: "WorkspacePath" };

/** An absolute directory the host chose. Mutable code never supplies one. */
export type WorkspaceRoot = string & { readonly [workspaceRootBrand]: "WorkspaceRoot" };

/** A non-empty argument vector. There is no shell-string form on this surface. */
export type ExecArgv = readonly [string, ...string[]] & { readonly [execArgvBrand]: "ExecArgv" };
```

```ts
// src/model-route/index.ts
declare const modelRouteBrand: unique symbol;

/** The single origin plus path prefix the generation may reach. */
export type ModelRoute = string & { readonly [modelRouteBrand]: "ModelRoute" };
```

`HarnessCommit` already exists in `src/harness-commit.ts` and is reused unchanged.

## Function signatures

### Tenant derivation

```ts
// src/tenant/access-jwt.ts

export type AccessRejection =
  | { readonly code: "missing-assertion" }
  | { readonly code: "malformed-token" }
  | { readonly code: "unknown-key"; readonly keyId: string }
  | { readonly code: "bad-signature" }
  | { readonly code: "wrong-issuer"; readonly issuer: string }
  | { readonly code: "wrong-audience" }
  | { readonly code: "expired"; readonly expiredAtMs: number }
  | { readonly code: "not-yet-valid"; readonly notBeforeMs: number }
  | { readonly code: "missing-subject" }
  | { readonly code: "key-fetch-failed" };

export type AccessPolicy = {
  readonly issuer: string;
  readonly audience: AccessAudience;
  readonly clockSkewMs: number;
};

/** Pure. Splits and base64url-decodes without checking anything cryptographic. */
export function decodeAccessToken(raw: string): Result<DecodedAccessToken, AccessRejection> {
  throw new Error("not implemented");
}

/** Pure. Every claim rule lives here so the rejection table is testable without crypto. */
export function checkAccessClaims(
  token: DecodedAccessToken,
  policy: AccessPolicy,
  nowMs: number,
): Result<AccessIdentity, AccessRejection> {
  throw new Error("not implemented");
}

/**
 * Shell. Reads `Cf-Access-Jwt-Assertion`, decodes, resolves the signing key,
 * verifies RS256 through `crypto.subtle`, then applies `checkAccessClaims`.
 * Fails closed when the key set cannot be fetched.
 */
export function verifyAccessIdentity(
  request: Request,
  policy: AccessPolicy,
  keys: AccessKeyCache,
  nowMs: number,
): Promise<Result<AccessIdentity, AccessRejection>> {
  throw new Error("not implemented");
}
```

