### Documents

```ts
// src/workspace-host/documents/index.ts

export function parseDocumentKey(value: string): DocumentKey | undefined {
  throw new Error("not implemented");
}

export type DocumentRead =
  | { readonly found: true; readonly key: string; readonly revision: number; readonly value: string; readonly updatedAtMs: number }
  | { readonly found: false; readonly key: string };

export type DocumentWrite = {
  readonly key: string;
  /** `null` asserts the key does not exist yet. */
  readonly expectedRevision: number | null;
  readonly value: string;
};

export type DocumentWriteResult =
  | { readonly ok: true; readonly revision: number; readonly updatedAtMs: number }
  | { readonly ok: false; readonly code: "revision-conflict"; readonly actualRevision: number | null }
  | { readonly ok: false; readonly code: "invalid-key" }
  | { readonly ok: false; readonly code: "value-too-large"; readonly limitBytes: number };

export type DocumentHead = { readonly key: string; readonly revision: number; readonly updatedAtMs: number };

/**
 * Opaque compare-and-swap storage. The store has no parse function and no
 * schema for a value, so a generation owns the format and every migration of it.
 */
export class DocumentStore {
  constructor(storage: DurableObjectStorage) {
    throw new Error("not implemented");
  }

  read(key: DocumentKey): DocumentRead {
    throw new Error("not implemented");
  }

  /** Read, compare, write inside one `transactionSync`. The DO is single-threaded, so that is atomic. */
  write(key: DocumentKey, expected: DocumentRevision | null, value: string, nowMs: number): DocumentWriteResult {
    throw new Error("not implemented");
  }

  list(prefix: DocumentKey): readonly DocumentHead[] {
    throw new Error("not implemented");
  }
}
```

