type ProbeFacetEnv = { readonly HOST: MainHarnessHostBinding };

export class MainFacet extends DurableObject<ProbeFacetEnv> {
  override fetch(): Promise<Response> {
    return runProbe(this.env.HOST, Date.now).then(
      (result) => new Response(JSON.stringify(result), { headers: { "content-type": "application/json" } }),
    );
  }
}

export default {
  fetch() {
    return new Response("probe facet: use the durable object", { status: 404 });
  },
};
