export type DocumentWriteResult =
  | { readonly kind: "written"; readonly revision: DocumentRevision }
  | {
      readonly kind: "conflict";
      readonly actual:
        | { readonly kind: "missing" }
        | { readonly kind: "revision"; readonly revision: DocumentRevision };
